INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$"Required" means no one gets enough deep sleep without afternoon exercise. The study only shows exercisers got *more* deep sleep.$batch08$), ($batch08$B$batch08$, $batch08$The mechanism depends on body heat lasting until bedtime. Morning exercise is never discussed, and its heat could easily wear off by night.$batch08$), ($batch08$C$batch08$, $batch08$"The best way" needs a comparison with every other method. The passage describes one method that works.$batch08$), ($batch08$D$batch08$, $batch08$This is the most popular wrong answer. "No one" covers every person in the control group. They exercised little, but someone could have been warmed by a hot meal or a fever. The study reports group results, not every individual.$batch08$), ($batch08$E$batch08$, $batch08$The researcher says the deep sleep comes from a slight rise in body temperature lasting past bedtime. A warm bath right before bed creates that same condition, so it should help too. "Will likely" is exactly as strong as the mechanism allows.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT119-S2-Q12$batch08$ AND e.id=$batch08$ba027d65-3993-417a-9d15-840243736e99$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
